const API_URL = "http://localhost:8085/v1/api/RapidAPI";

export const getAllMovies = () => axios.get(`${API_URL}/Disney/GetAll`);
export const createMovie = (movie) => axios.post(`${API_URL}/Disney/save`, movie);
export const updateMovie = (movie) => axios.put(`${API_URL}/Disney/Mongo/update`, movie);
export const changeMovieStatus = (id, status) => axios.patch(`${API_URL}/Disney/Mongo/changeStatus/${id}?status=${status}`);
export const searchMovieFull = (name) => axios.get(`${API_URL}/Disney/API/searchFull/${name}`);
